CREATE TABLE IF NOT EXISTS "user" (id SERIAL PRIMARY KEY, login VARCHAR(50) NOT NULL, email VARCHAR(100) NOT NULL, password_hash VARCHAR(500) NOT NULL, phone VARCHAR(50) NOT NULL, last_name VARCHAR(100) NOT NULL, first_name VARCHAR(100) NOT NULL, patronymic VARCHAR(100) NOT NULL, access_token VARCHAR(300) NOT NULL, refresh_token VARCHAR(300) NOT NULL);
CREATE SEQUENCE IF NOT EXISTS user_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
